CREATE OR REPLACE FUNCTION public.autoflag_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_text     text;
  v_action   text;
  v_category text;
  v_note     text;
BEGIN
  IF TG_TABLE_NAME = 'gratitude_entries' THEN
    IF NEW.is_shared IS NOT TRUE THEN RETURN NEW; END IF;
    v_text := concat_ws(' ', NEW.item_1, NEW.item_2, NEW.item_3, to_jsonb(NEW) ->> 'payload');
  ELSE
    v_text := NEW.content;
  END IF;

  -- moderation_verdict 已依嚴重度排序（block > hide > flag），取第一筆非 block 的。
  SELECT v.action, v.category INTO v_action, v_category
    FROM moderation_verdict(v_text) v WHERE v.action IN ('hide', 'flag') LIMIT 1;
  IF v_action IS NULL THEN RETURN NEW; END IF;

  v_note := CASE v_action
    WHEN 'hide' THEN '系統自動隱藏並送人工審核（鼓勵自傷／自殺等高風險內容）'
    ELSE '系統自動標記（輕度違規字詞）'
  END;

  IF TG_TABLE_NAME = 'gratitude_entries' THEN
    INSERT INTO reports (reporter_id, source, target_type, entry_id, reported_user_id, reasons, note)
    VALUES (NULL, 'auto', 'entry', NEW.id, NEW.user_id, ARRAY[v_category], v_note)
    ON CONFLICT DO NOTHING;
  ELSE
    INSERT INTO reports (reporter_id, source, target_type, comment_id, reported_user_id, reasons, note)
    VALUES (NULL, 'auto', 'comment', NEW.id, NEW.user_id, ARRAY[v_category], v_note)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.autohide_reported_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
  v_threshold int := 2;
BEGIN
  IF NEW.reporter_id IS NOT NULL AND NEW.reasons @> ARRAY['self_harm_promotion'] THEN
    v_threshold := 1;
  END IF;

  IF NEW.target_type = 'entry' AND NEW.entry_id IS NOT NULL THEN
    SELECT count(DISTINCT reporter_id) INTO v_count
      FROM reports WHERE entry_id = NEW.entry_id AND reporter_id IS NOT NULL;
    IF v_count >= v_threshold THEN
      UPDATE gratitude_entries
        SET moderation_status = 'hidden',
            moderated_at = now(),
            moderation_note = CASE WHEN v_threshold = 1
              THEN '檢舉為鼓勵自傷／自殺，系統立即隱藏待審'
              ELSE '多人檢舉，系統自動隱藏待審' END
        WHERE id = NEW.entry_id AND moderation_status = 'ok';
    END IF;
  ELSIF NEW.target_type = 'comment' AND NEW.comment_id IS NOT NULL THEN
    SELECT count(DISTINCT reporter_id) INTO v_count
      FROM reports WHERE comment_id = NEW.comment_id AND reporter_id IS NOT NULL;
    IF v_count >= v_threshold THEN
      UPDATE comments
        SET moderation_status = 'hidden',
            moderated_at = now(),
            moderation_note = CASE WHEN v_threshold = 1
              THEN '檢舉為鼓勵自傷／自殺，系統立即隱藏待審'
              ELSE '多人檢舉，系統自動隱藏待審' END
        WHERE id = NEW.comment_id AND moderation_status = 'ok';
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.enforce_content_moderation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_text    text;
  v_action  text;
  v_category text;
  -- 這則內容「原本」是不是已經公開的。只有 gratitude_entries 的 UPDATE 會用到，
  -- 其餘情況維持 false（見下方取值處的說明）。
  v_was_shared boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'gratitude_entries' THEN
    IF NEW.is_shared IS NOT TRUE THEN RETURN NEW; END IF;
    -- payload 欄位在部分環境可能還沒建立（process_goal.sql 未跑），
    -- 用 to_jsonb(NEW) 取值，欄位不存在就是 NULL，不會讓觸發器整個炸掉。
    v_text := concat_ws(' ', NEW.item_1, NEW.item_2, NEW.item_3, to_jsonb(NEW) ->> 'payload');
  ELSE
    v_text := NEW.content;
  END IF;

  -- 停權中的使用者不得發佈新的公開內容（1.2：移除違規者）。
  -- 注意這段在上面「私人日記直接放行」之後：被停權的人仍然寫得了私人日記——
  -- 他失去的是社群，不是這個 App 本來要給他的心理健康工具。
  --
  -- 除了新建，「把舊的私人貼文改成公開」也要擋（否則停權期間照樣能發文，
  -- 只要先存私人再切公開就行了）；但改回私人、改內容、刪除都放行，
  -- 讓他仍能收拾自己的東西。
  --
  -- ⚠️ OLD 只能在「gratitude_entries 的 UPDATE」這一種情況下碰，而且必須先取進
  --    變數、不能直接寫在下面的 IF 條件裡。原本寫成
  --      AND (TG_OP = 'INSERT' OR (TG_TABLE_NAME = 'gratitude_entries' AND OLD.is_shared IS NOT TRUE))
  --    看起來有 TG_OP / TG_TABLE_NAME 擋著，實際上 PL/pgSQL 不保證布林運算短路，
  --    OLD.is_shared 的欄位解析照樣會發生：
  --      · INSERT 時 OLD 未賦值
  --      · comments 表根本沒有 is_shared 這個欄位
  --    兩者都會拋 42703 record "old" has no field "is_shared"。
  --    結果是**每一次留言、每一篇公開貼文都寫不進去**（2026-09-11 線上事故）。
  IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'gratitude_entries' THEN
    v_was_shared := COALESCE(OLD.is_shared, false);
  END IF;

  IF is_suspended(NEW.user_id)
     AND (TG_OP = 'INSERT' OR (TG_TABLE_NAME = 'gratitude_entries' AND NOT v_was_shared))
  THEN
    RAISE EXCEPTION 'CONTENT_BLOCKED: suspended 帳號目前因違反社群守則被暫停發文';
  END IF;

  SELECT v.action, v.category INTO v_action, v_category FROM moderation_verdict(v_text) v LIMIT 1;
  IF v_action = 'block' THEN
    RAISE EXCEPTION 'CONTENT_BLOCKED: % 內容違反社群守則', v_category;
  END IF;

  -- 'hide'：寫得進去，但一出生就是隱藏狀態，公開動態牆看不到
  -- （RLS 只放行 moderation_status = 'ok'；作者自己仍讀得到，不會以為資料不見）。
  -- 對應的待審紀錄由 AFTER 觸發器 autoflag_content() 開，兩支合起來才是
  -- 「flag + 立即隱藏 + 人工審核」。
  --
  -- 這裡刻意不 RAISE：一來要留下證據給人審與累犯判斷，二來不告訴發文者
  -- 「哪個字被抓到」，否則規則清單等於公開，換個寫法就繞過去了。
  IF v_action = 'hide' THEN
    NEW.moderation_status := 'hidden';
    NEW.moderated_at      := now();
    NEW.moderation_note   := format('系統自動隱藏待審（%s）', v_category);
  END IF;

  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.get_my_entitlements()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid          uuid := auth.uid();
  v_tier       text := 'free';
  v_status     text := 'active';
  v_founding   boolean := false;
  v_expires    timestamptz;
  v_pro        boolean;
  v_limit      integer;
  v_used       integer;
  v_perma_used integer;
BEGIN
  IF uid IS NULL THEN
    RETURN jsonb_build_object('tier', 'anonymous', 'is_pro', false);
  END IF;

  -- 查無訂閱列 = 免費層（絕大多數既有使用者），不可報錯。
  SELECT s.tier, s.status, s.is_founding_member, s.expires_at
    INTO v_tier, v_status, v_founding, v_expires
  FROM subscriptions s WHERE s.user_id = uid;
  IF NOT FOUND THEN
    v_tier := 'free'; v_status := 'active'; v_founding := false;
  END IF;

  v_pro   := is_pro(uid);
  -- ⚠️ 2026-09-01 起 AI 分析不再有份數上限（見檔案開頭）。-1 代表「不限」，
  --    另外附上 unlimited 旗標讓前端不必去解讀這個數字。
  v_limit := -1;
  v_used  := weekly_analysis_used(uid);

  SELECT count(*)::int INTO v_perma_used FROM perma_scores WHERE user_id = uid;

  RETURN jsonb_build_object(
    'tier',               v_tier,
    'status',             v_status,
    'is_pro',             v_pro,
    -- ⚠️ 純標籤：只給貼文徽章／個人頁顯示用，**不影響任何權益**（見 is_pro()）。
    'is_founding_member', v_founding,
    'expires_at',         v_expires,
    'weekly_analysis', jsonb_build_object(
      'period',       CASE WHEN v_pro THEN 'week' ELSE 'month' END,
      'period_start', weekly_analysis_period_start(uid),
      'unlimited',    true,
      'limit',        v_limit,    -- -1 = 不限
      'used',         v_used,
      'remaining',    -1
    ),
    'community', jsonb_build_object(
      'unlimited',             v_pro,
      'unlocked',              community_unlocked(uid),
      'contributed_this_week', EXISTS (
        SELECT 1 FROM gratitude_entries
        WHERE user_id = uid AND is_shared = true AND created_at >= date_trunc('week', now())
      ),
      -- 未貢獻時能看幾則，讀 paywall_config；查不到設定時保守退回 15。
      'free_view_limit', COALESCE((SELECT free_view_limit FROM paywall_config WHERE id = 1), 15)
    ),
    'baseline_assessment', jsonb_build_object(
      'used',          v_perma_used,
      'can_retake',    true   -- 暫不限制重測次數，免費層也能無限重測
    ),
    -- 月報告／趨勢／成長對照這些功能目前尚未實作，先預留旗標供日後接上。
    'can_view_trends', v_pro,
    'can_view_growth_comparison', v_pro
  );
END; $function$

CREATE OR REPLACE FUNCTION public.notify_push_on_interaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Environment-specific integration: disabled unless explicitly configured.
  IF current_setting('mindgym.notifications_enabled', true) IS DISTINCT FROM 'on' THEN
    RETURN NEW;
  END IF;
  PERFORM net.http_post(
    url := current_setting('mindgym.push_url', true),
    headers := jsonb_build_object(
                 'Content-Type', 'application/json',
                 'x-webhook-secret', current_setting('mindgym.webhook_secret', true)
               ),
    body    := jsonb_build_object(
                 'type',  'INSERT',
                 'table', TG_TABLE_NAME,
                 'record', to_jsonb(NEW)
               )
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_invite_code(p_code text, p_share_perma boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module_id uuid;
  v_owner_id  uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION '需要登入'; END IF;
  SELECT m.id, m.owner_id INTO v_module_id, v_owner_id
  FROM invite_codes c JOIN pro_modules m ON m.id = c.module_id
  WHERE c.code = upper(trim(p_code)) AND c.is_active
    AND m.published_content IS NOT NULL AND m.status <> 'archived'
  LIMIT 1;
  IF v_module_id IS NULL THEN RETURN NULL; END IF;

  INSERT INTO pro_enrollments (module_id, user_id, practitioner_id, status, share_perma, consented_at, stopped_at)
  VALUES (v_module_id, auth.uid(), v_owner_id, 'active', COALESCE(p_share_perma, false), now(), NULL)
  ON CONFLICT (module_id, user_id) DO UPDATE
    SET status = 'active', share_perma = EXCLUDED.share_perma,
        practitioner_id = EXCLUDED.practitioner_id, consented_at = now(), stopped_at = NULL;

  RETURN (
    SELECT json_build_object(
      'module_id', m.id, 'title', m.title, 'description', m.description,
      'est_minutes', m.est_minutes, 'kind', m.kind,
      'practitioner_name', (SELECT name FROM profiles WHERE id = m.owner_id)
    ) FROM pro_modules m WHERE m.id = v_module_id
  );
END; $function$

CREATE OR REPLACE FUNCTION public.regenerate_invite_code(p_module_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_code text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pro_modules WHERE id = p_module_id AND owner_id = auth.uid())
    THEN RAISE EXCEPTION '僅限模組擁有者操作'; END IF;
  UPDATE invite_codes SET is_active = false, revoked_at = now()
    WHERE module_id = p_module_id AND is_active;
  -- 8 碼、排除易混淆字元（0O1IL），約 31^8 ≈ 8500 億組合，足以抵擋暴力猜測
  SELECT string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789',
    (floor(random() * 31) + 1)::int, 1), '') INTO v_code FROM generate_series(1, 8);
  INSERT INTO invite_codes (module_id, code) VALUES (p_module_id, v_code);
  RETURN v_code;
END; $function$

CREATE OR REPLACE FUNCTION public.schedule_bot_likes(p_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_already int;
  v_count   int;
  i         int;
  v_delay   int;
BEGIN
  -- 避免同一則貼文重複安排
  SELECT count(*) INTO v_already FROM bot_like_queue WHERE entry_id = p_entry_id;
  IF v_already > 0 THEN RETURN; END IF;

  v_count := 5 + floor(random() * 6)::int; -- 5 到 10 個讚
  FOR i IN 1..v_count LOOP
    v_delay := 60 + floor(random() * 5340)::int; -- 1~90 分鐘（秒數）
    INSERT INTO bot_like_queue (entry_id, scheduled_at)
    VALUES (p_entry_id, now() + (v_delay || ' seconds')::interval);
  END LOOP;
END;
$function$
